/**
 * API 工具模块
 * 提供防重放攻击的签名请求功能
 */

// 签名请求事件名
const SIGN_REQUEST_EVENT = 'finzktrust:sign-request';
const SIGN_RESPONSE_EVENT = 'finzktrust:sign-response';

/**
 * 生成32位随机字符串
 * @returns {string} 32位随机字符串
 */
const generateNonce = () => {
  let nonce = '';
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for (let i = 0; i < 32; i++) {
    nonce += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return nonce;
};

/**
 * 封装的fetch请求，自动添加防重放攻击所需的请求头
 * @param {string} url 请求URL
 * @param {Object} options 请求选项
 * @param {boolean} skipSignature 是否跳过SM2签名（用于注册等不需要签名的接口）
 * @returns {Promise} fetch请求的Promise
 */
export const fetchWithAntiReplay = async (url, options = {}, skipSignature = false) => {
  // 添加Authorization头
  const token = localStorage.getItem('token');
  if (token) {
    options.headers = {
      ...options.headers,
      'Authorization': `Bearer ${token}`
    };
  }

  // 确保Content-Type头
  if (options.method === 'POST' && !options.headers?.['Content-Type']) {
    options.headers = {
      ...options.headers,
      'Content-Type': 'application/json'
    };
  }

  // 对POST请求添加防重放攻击请求头（除非明确跳过）
  if (options.method === 'POST' && !skipSignature) {
    // 生成时间戳和随机数
    const timestamp = Date.now().toString();
    const nonce = generateNonce();

    // 获取请求体
    const requestBody = options.body || JSON.stringify({});

    // 构建签名原文：时间戳+随机数+请求体JSON字符串
    const signatureData = timestamp + nonce + requestBody;

    // 通过自定义事件请求 App.js 完成签名
    try {
      const signature = await new Promise((resolve, reject) => {
        const requestId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
        console.log('[apiUtils] 请求签名，requestId:', requestId);
        const timeout = setTimeout(() => {
          console.log('[apiUtils] 签名请求超时，requestId:', requestId);
          window.removeEventListener(SIGN_RESPONSE_EVENT, handler);
          resolve(null); // 超时降级为不带签名发送
        }, 5000);

        const handler = (e) => {
          console.log('[apiUtils] 收到签名响应，requestId:', requestId, '响应requestId:', e.detail?.requestId, 'signature:', e.detail?.signature ? '存在' : 'null');
          if (e.detail.requestId !== requestId) return;
          clearTimeout(timeout);
          window.removeEventListener(SIGN_RESPONSE_EVENT, handler);
          resolve(e.detail.signature || null);
        };

        window.addEventListener(SIGN_RESPONSE_EVENT, handler);
        window.dispatchEvent(new CustomEvent(SIGN_REQUEST_EVENT, {
          detail: { data: signatureData, requestId }
        }));
        console.log('[apiUtils] 已派发签名请求事件，requestId:', requestId);
      });

      if (signature) {
        options.headers = {
          ...options.headers,
          'X-Request-Timestamp': timestamp,
          'X-Request-Nonce': nonce,
          'X-Request-Sign': signature
        };
      }
    } catch (err) {
      console.warn('[apiUtils] 签名请求失败，将不带签名发送:', err.message);
    }
  }

  // 执行fetch请求
  return fetch(url, options);
};

/**
 * 简化的POST请求函数
 * @param {string} url 请求URL
 * @param {Object} data 请求数据
 * @param {boolean} skipSignature 是否跳过SM2签名（用于注册等不需要签名的接口）
 * @returns {Promise} fetch请求的Promise
 */
export const post = async (url, data, skipSignature = false) => {
  return fetchWithAntiReplay(url, {
    method: 'POST',
    body: JSON.stringify(data)
  }, skipSignature);
};

/**
 * 简化的GET请求函数
 * @param {string} url 请求URL
 * @returns {Promise} fetch请求的Promise
 */
export const get = async (url) => {
  return fetchWithAntiReplay(url, {
    method: 'GET'
  });
};