import { Skeleton, Card, CardContent, CardHeader, Table, TableBody, TableCell, TableHead, TableRow, Box } from '@mui/material';

export const CardSkeleton = ({ count = 1 }) => {
  return Array.from({ length: count }).map((_, index) => (
    <Card key={index} sx={{ mb: 2 }}>
      <CardHeader
        title={<Skeleton variant="text" width="60%" height={32} />}
      />
      <CardContent>
        <Skeleton variant="text" />
        <Skeleton variant="text" />
        <Skeleton variant="text" width="70%" />
      </CardContent>
    </Card>
  ));
};

export const TableSkeleton = ({ rows = 3, columns = 4 }) => {
  return (
    <Box>
      <Skeleton variant="rectangular" height={48} sx={{ mb: 1 }} />
      {Array.from({ length: rows }).map((_, rowIndex) => (
        <Box key={rowIndex} sx={{ display: 'flex', gap: 1, py: 0.5 }}>
          {Array.from({ length: columns }).map((_, colIndex) => (
            <Skeleton key={colIndex} variant="text" width={`${100 / columns}%`} />
          ))}
        </Box>
      ))}
    </Box>
  );
};

export const FormSkeleton = () => {
  return (
    <Box>
      <Skeleton variant="text" width="30%" sx={{ mb: 1 }} />
      <Skeleton variant="rectangular" height={56} sx={{ mb: 2 }} />
      <Skeleton variant="text" width="30%" sx={{ mb: 1 }} />
      <Skeleton variant="rectangular" height={56} sx={{ mb: 2 }} />
      <Skeleton variant="rectangular" height={48} width="40%" />
    </Box>
  );
};

export const ProfileSkeleton = () => {
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', py: 3 }}>
      <Skeleton variant="circular" width={100} height={100} sx={{ mb: 2 }} />
      <Skeleton variant="text" width="50%" height={32} sx={{ mb: 2 }} />
      <Skeleton variant="text" width="30%" sx={{ mb: 1 }} />
      <Skeleton variant="text" width="40%" sx={{ mb: 1 }} />
      <Skeleton variant="text" width="30%" sx={{ mb: 1 }} />
      <Skeleton variant="text" width="40%" />
    </Box>
  );
};

export const PoolInfoSkeleton = () => {
  return (
    <Box>
      <Skeleton variant="text" width="40%" height={40} sx={{ mb: 2 }} />
      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
        {[1, 2, 3, 4].map((item) => (
          <Card key={item} sx={{ flex: '1 1 200px', minWidth: 200 }}>
            <CardContent>
              <Skeleton variant="text" width="50%" />
              <Skeleton variant="text" width="70%" height={36} />
            </CardContent>
          </Card>
        ))}
      </Box>
    </Box>
  );
};