import React, { useState } from 'react';
import { Container, Paper, Typography, TextField, Button, Box, Alert, Collapse } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import { useNavigate } from 'react-router-dom';

const API_BASE = 'http://localhost:3003/api/v1';

function MfaVerify({ onLoginSuccess }) {
  const [token, setToken] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showBackupCodes, setShowBackupCodes] = useState(false);
  const navigate = useNavigate();

  const handleVerify = async () => {
    if (token.length !== 6 && token.length !== 8) {
      setError('请输入6位验证码或8位备用码');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const tempToken = localStorage.getItem('tempToken');
      if (!tempToken) {
        setError('临时令牌已过期，请重新登录');
        return;
      }

      const response = await fetch(`${API_BASE}/mfa/verify`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${tempToken}`
        },
        body: JSON.stringify({ token })
      });

      const data = await response.json();
      if (data.success) {
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        localStorage.removeItem('tempToken');
        window.dispatchEvent(new CustomEvent('mfaVerified', { detail: data }));
        navigate('/profile');
      } else {
        setError(data.message || '验证码无效');
      }
    } catch (err) {
      setError('网络错误，请稍后重试');
    } finally {
      setLoading(false);
    }
  };

  const handleBackToLogin = () => {
    localStorage.removeItem('tempToken');
    navigate('/');
  };

  return (
    <Container maxWidth="sm" sx={{ mt: 8 }}>
      <Paper sx={{ p: 4 }}>
        <Typography variant="h5" gutterBottom>
          双因子验证
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          请输入身份验证器中的6位验证码
        </Typography>

        {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

        <TextField
          fullWidth
          value={token}
          onChange={(e) => setToken(e.target.value.replace(/\s/g, ''))}
          placeholder={showBackupCodes ? "8位备用码" : "6位验证码"}
          inputProps={{ maxLength: showBackupCodes ? 8 : 6 }}
          sx={{ mb: 2 }}
        />

        <Button
          variant="contained"
          color="primary"
          fullWidth
          onClick={handleVerify}
          disabled={loading}
          sx={{ mb: 2 }}
        >
          {loading ? '验证中...' : '验证'}
        </Button>

        <Box sx={{ textAlign: 'center', mb: 2 }}>
          <Button
            onClick={() => setShowBackupCodes(!showBackupCodes)}
            endIcon={showBackupCodes ? <ExpandLessIcon /> : <ExpandMoreIcon />}
          >
            {showBackupCodes ? '使用验证码登录' : '使用备用码登录'}
          </Button>
        </Box>

        <Button
          variant="text"
          fullWidth
          onClick={handleBackToLogin}
        >
          返回登录
        </Button>
      </Paper>
    </Container>
  );
}

export default MfaVerify;